package com.railflow.yardops.api;
import com.railflow.yardops.repository.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class ApiIntegrationTest { @Autowired MockMvc mvc; @Autowired ShipmentRepository shipments; @BeforeEach void reset(){shipments.deleteAll();} @Test void createsAndListsShipment() throws Exception {mvc.perform(post("/api/shipments").contentType(MediaType.APPLICATION_JSON).content("{\"reference\":\"RF-TEST\",\"origin\":\"NPT\",\"destination\":\"KCM\",\"commodity\":\"Grain\",\"customer\":\"Test\",\"priority\":\"HIGH\"}")) .andExpect(status().isOk()).andExpect(jsonPath("$.reference").value("RF-TEST"));mvc.perform(get("/api/shipments")).andExpect(status().isOk()).andExpect(jsonPath("$[0].reference").value("RF-TEST"));} }